import sys

def solve() -> None:
    input = sys.stdin.readline
    n = int(input())
    a = [0] + list(map(int, input().split()))
    g = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u, v = map(int, input().split())
        g[u].append(v)
        g[v].append(u)

    res = 0
    cum = [0, 0]  # cum[0] 偶深度累积异或, cum[1] 奇深度累积异或

    # 栈元素: (当前节点, 父节点, 深度, 阶段, 操作值x)
    stk = [(1, 0, 0, 0, 0)]
    while stk:
        u, p, d, stage, x = stk.pop()
        if stage == 0:
            pp = d & 1
            need = cum[pp] ^ a[u]  # 当前实际值，需要异或的x
            res += need
            cum[pp] ^= need
            # 回溯阶段入栈
            stk.append((u, p, d, 1, need))
            for v in g[u]:
                if v != p:
                    stk.append((v, u, d + 1, 0, 0))
        else:
            # 回溯，撤销当前节点对累积异或的影响
            pp = d & 1
            cum[pp] ^= x

    print(res)

if __name__ == "__main__":
    solve()
```

